"""Add continuous certificates to the existing chemistry response reader."""
from fractions import Fraction as F
import hashlib,json
import markdown
from chemistry_continuous_data import AREA,DATA,build as build_data,replay

PROOF='read/computational-chemistry/continuous.html'
def add(site,body,polynomial=None):
    raw=(site.root/DATA).read_bytes();data=json.loads(raw)
    if raw!=(json.dumps(build_data(site.root),separators=(',',':'))+'\n').encode():raise ValueError('Stale continuous fixture')
    digest=hashlib.sha256(raw).hexdigest();site.write('assets/chemistry/continuous-v1.json',raw.decode())
    def asset(name,payload=None):
        payload=payload if payload is not None else (site.root/'website/assets'/name).read_bytes()
        return 'assets/'+name+'?v='+hashlib.sha256(payload).hexdigest()[:12]
    shared='chemistry-lab-core.mjs';site.write('assets/'+shared,(site.root/'website/assets'/shared).read_text(encoding='utf-8'))
    core=(site.root/'website/assets/chemistry-continuous-core.mjs').read_text(encoding='utf-8').replace("'./chemistry-lab-core.mjs'","'./"+asset(shared).removeprefix('assets/')+"'")
    site.write('assets/chemistry-continuous-core.mjs',core)
    script=(site.root/'website/assets/chemistry-continuous.js').read_text(encoding='utf-8').replace("'./chemistry-continuous-core.mjs'","'./"+asset('chemistry-continuous-core.mjs',core.encode()).removeprefix('assets/')+"'")
    if polynomial:script=script.replace("'./chemistry-polynomial-core.mjs'","'./"+polynomial['core_source'].removeprefix('assets/')+"'")
    site.write('assets/chemistry-continuous.js',script);site.write('assets/chemistry-continuous.css',(site.root/'website/assets/chemistry-continuous.css').read_text(encoding='utf-8'))
    package=replay(site.root);target=site.output/'assets/chemistry/stage16-replay.zip';target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(package);package_hash=hashlib.sha256(package).hexdigest()
    for name in ['CONTINUOUS_RESPONSES.md','SELF_REVIEW.json']:
        target=site.output/'assets/chemistry/stage16'/name;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes((site.root/AREA/name).read_bytes())
    note=(site.root/AREA/'CONTINUOUS_RESPONSES.md').read_text(encoding='utf-8');proof=markdown.markdown(note,extensions=['fenced_code'])
    site.page(PROOF,'Continuous energy response certificates','<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="../../chemistry-responses.html#cr-continuous">Response explorer</a> / Continuous certificates</nav>'+proof+'<p><a href="../../assets/chemistry/stage16/CONTINUOUS_RESPONSES.md">Markdown source</a> · <a href="../../assets/chemistry/stage16/SELF_REVIEW.json">Project self-review</a></p>','https://github.com/KomorebiP/Operation-KOMOREBI/blob/'+site.revision+'/'+(AREA/'CONTINUOUS_RESPONSES.md').as_posix())
    rows=[]
    for eta,k in [('1/2',32),('1/10',128),('1/100',512)]:
        c=next(c for c in data['groups'] if c['eta']==eta and c['order']==k)
        rows.append('<tr><th scope="row">'+str(float(F(eta)))+'</th><td>'+str(k)+'</td><td>'+str(len(c['points']))+'</td><td>≈ '+f"{float(F(c['maximum_radius'])):.6g}"+'</td><td>'+('≈ '+f"{float(F(c['whole_interval_gap'])):.6g}" if F(c['whole_interval_gap'])>0 else 'No positive bound')+'</td></tr>')
    n=data['narrow'];prefix=n['prefixes'];r256=next(p['maximum_sample_radius'] for p in prefix if p['order']==256);r512=next(p['maximum_sample_radius'] for p in prefix if p['order']==512)
    section='''<link rel="stylesheet" href="'''+asset('chemistry-continuous.css')+'''">
<section class="cr-panel" id="cr-continuous"><p class="cr-eyebrow">02 / Between the sampled energies</p><h2>A bound for the whole energy interval.</h2><p>The first experiment certifies individual samples. This one also accounts for the response between them. The shaded bands use a proved interpolation bound and the existing endpoint disks.</p>
<div id="cc-lab" data-source="'''+asset('chemistry/continuous-v1.json')+'''" data-sha256="'''+digest+'''"><p id="cc-status" role="status">Loading the interval controls. The continuous results and theorem below are available now.</p><button type="button" id="cc-retry" hidden>Retry loading continuous certificates</button><noscript><p>The table, theorem and complete replay remain available without JavaScript.</p></noscript>
<div id="cc-explorer" hidden><div class="cr-controls"><div><label for="cc-eta">Broadening η (Hartree)</label><select id="cc-eta"><option value="1/100">0.01 — finer features</option><option value="1/10" selected>0.1</option><option value="1/2">0.5 — broader features</option></select></div><div><label for="cc-order">Full-target actions in the cache</label><select id="cc-order"><option>128</option></select></div></div>
<figure class="cr-figure"><figcaption>Continuous local-removal response bounds, per Hartree</figcaption><div id="cc-plot"></div><p class="cr-legend"><span class="cr-full">● Full finite-model response</span><span class="cr-reduced">◆ Nine-state response</span></p><p id="cc-plot-note"></p></figure>
<label for="cc-position">Choose an energy within the interval <output id="cc-position-value" for="cc-position"></output></label><input id="cc-position" type="range" min="0" max="400" step="1" value="205"><p class="cr-result" id="cc-result" role="status" aria-live="polite" aria-atomic="true"></p><dl class="cr-values" id="cc-values"></dl><p id="cc-gap"></p><div class="cr-actions"><button id="cc-download" type="button">Download interval certificate</button><a href="chemistry-responses.html#cr-continuous" id="cc-link">Link to this energy</a><button id="cc-reset" type="button">Reset continuous scan</button></div><details><summary>Inspect the exact interval certificate</summary><pre id="cc-certificate" tabindex="0" role="group" aria-label="Interval certificate; scroll horizontally if needed"></pre></details></div></div>
<h3>From isolated samples to complete coverage</h3><div class="cr-table" tabindex="0" role="group" aria-label="Continuous scan results; scroll horizontally if needed"><table><caption>Bounds over the whole removal-energy interval [−0.70, −0.30] Hartree</caption><thead><tr><th scope="col">η (Ha)</th><th scope="col">H actions</th><th scope="col">Endpoint energies</th><th scope="col">Maximum radius, per Ha</th><th scope="col">Model discrepancy lower bound, per Ha</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div>
<p>At η = 0.1, the full and nine-state imaginary responses differ by more than 0.02365 per Hartree at every energy in the interval. A missing positive discrepancy bound means the certificate does not prove separation; it does not establish agreement.</p>
<p>The narrow η = 0.01 calculation uses 512 actions. In that run, doubling the budget from 256 to 512 reduced the largest radius at the original 41 samples from approximately '''+f'{r256:.4g}'+''' to '''+f'{r512:.4g}'+''' per Hartree. Refining the mesh to '''+str(n['nodes'])+''' endpoint energies then bounded the response across every cell with radius below 0.1 per Hartree. The '''+str(n['nodes']-41)+''' additional energies required zero additional Hamiltonian actions.</p>
<p>The 0.1 precision budget is an illustrative absolute response tolerance for this fixed model. It is not a universal chemistry accuracy criterion. Short decimals and plots are approximate; certificate calculations use exact fractions and outward enclosures.</p>
<details><summary>Read the continuous bound</summary><p>For one Hermitian H and one fixed source, let g(E) be its resolvent response at positive broadening η. At cell endpoints a and c, suppose the response disks have centers c₀,c₁ and radii r₀,r₁. Set h = c − a, E = a + th, and Uⱼ = −Im(cⱼ) + rⱼ. Then, for every 0 ≤ t ≤ 1,</p><pre class="cc-equation">|g(E) − [(1−t)c₀ + tc₁]| ≤ (1−t)r₀ + tr₁ + t(1−t)C
C = (h²/η²) √(U₀U₁)
Radius valid throughout the cell: max(r₀,r₁) + C/4</pre><p>The browser checks the interpolation inequalities for every saved cell with BigInt fractions. This propagation retains the original endpoint arithmetic assumptions. The Hermitian hypothesis is essential; the replay includes an exact nonnormal counterexample.</p><p><a href="'''+PROOF+'''">Read the proof, scope and computation notes</a> · <a href="assets/chemistry/stage16/SELF_REVIEW.json">Read the project self-review</a></p></details>
<details><summary>Calculation and resource record</summary><p>The 512-action calculation used temporary file-backed basis arrays and bounded contraction buffers after the first allocation attempts failed. The blocked implementation applies the same exact operator and retains the same arithmetic error cap. Separate exact tests cover 73 small-model and nine full-target columns, 32 prepared-cache response inclusions, and 324 interpolation identities and disk inclusions.</p><p>The new run took approximately '''+f"{n['timings']['total_seconds']:.1f}"+''' seconds on this Windows environment with a one-thread request. Timings from different implementations are not an optimized-solver comparison. The failed attempts, source snapshots, active execution manifests and regeneration commands are retained.</p></details>
<div class="cr-actions"><a href="assets/chemistry/stage16-replay.zip" download>Download the continuous-response replay</a><a href="assets/chemistry/continuous-v1.json">Inspect continuous certificate data</a></div><p class="cr-small">Continuous replay SHA-256: <code class="cr-hash">'''+package_hash+'''</code></p><p>These bounds cover the declared finite Hamiltonian and fixed supplied source/reference. Neutral-source accuracy, basis error and physical prediction remain separate obligations.</p></section><script type="module" src="'''+asset('chemistry-continuous.js',script.encode())+'''"></script>'''
    anchor='<section class="cr-panel" id="cr-reduction">'
    if polynomial:
        section=section.replace('id="cc-lab"','id="cc-lab" data-polynomial-source="'+polynomial['data_source']+'" data-polynomial-sha256="'+polynomial['data_sha256']+'"')
        section=section.replace('<div id="cc-explorer" hidden>','<p id="cc-poly-status" role="status">Loading the optional polynomial bounds.</p><button id="cc-poly-retry" type="button" hidden>Retry polynomial bounds</button><div id="cc-explorer" hidden>')
        section=section.replace('<figure class="cr-figure">','<div class="cp-method"><label for="cc-method">Interpolation method</label><select id="cc-method"><option value="linear">Linear — two saved values</option><option value="polynomial" disabled>Local polynomial — up to cubic</option></select></div><figure class="cr-figure">',1)
        section=section.replace('</select></div></div>\n<div class="cp-method">','</select></div><div class="cp-method">').replace('Local polynomial — up to cubic</option></select></div><figure','Local polynomial — up to cubic</option></select></div></div><figure')
    if body.count(anchor)!=1:raise ValueError('Missing response-reader insertion point')
    body=body.replace(anchor,section+anchor).replace('02 / Test the small model','03 / Test the small model').replace('03 / Keep the assumptions with the answer','04 / Keep the assumptions with the answer').replace('sampled energies per broadening','initial grid energies').replace('<a href="#cr-reduction">Check the reduction</a>','<a href="#cr-continuous">Between the samples</a><a href="#cr-reduction">Check the reduction</a>')
    site.search.append(dict(title='Continuous chemistry response certificates',group='Collection',kind='Examples',work_ids=[],url='chemistry-responses.html#cr-continuous',text='Continuous energy error bands interpolation all energies whole interval adaptive mesh 512 action cache source Krylov Hermitian resolvent exact fractions replay'))
    site.search.append(dict(title='Proof of continuous energy response bounds',group='Collection',kind='Notes',work_ids=[],url=PROOF,text='Hermitian resolvent interpolation identity endpoint imaginary response strength continuous disk Cauchy Schwarz nonnormal counterexample bounded memory prepared cache'))
    return body,dict(cells=sum(len(c['cells']) for c in data['groups']),data_sha256=digest,replay_sha256=package_hash,replay_bytes=len(package),narrow_actions=512,narrow_nodes=n['nodes'],narrow_tolerance=n['tolerance'])
